extends Node2D

var peer = ENetMultiplayerPeer.new()
@export var player_scene: PackedScene

func _on_host_btn_pressed():
	peer.create_server(7000) # Открываем порт 7000
	multiplayer.multiplayer_peer = peer
	add_player(multiplayer.get_unique_id()) # Добавляем себя
	$CanvasLayer/MainMenu.hide()

func _on_join_btn_pressed():
	var ip = $CanvasLayer/MainMenu/IPInput.text
	peer.create_client(ip, 7000) # Подключаемся к хосту
	multiplayer.multiplayer_peer = peer
	$CanvasLayer/MainMenu.hide()

# Функция вызывается на всех клиентах
@rpc("any_peer", "call_local")
func set_nick(new_name):
	$NameLabel.text = new_name

func _ready():
	if is_multiplayer_authority():
		set_nick.rpc(Global.name_user) # Рассылаем всем свое имя

func _on_body_entered(body):
	if not multiplayer.is_server(): return # Только сервер может удалять объекты

	if body.is_in_group('players'):
		# Сообщаем игроку, что он поднял гриб (через RPC)
		# И удаляем объект для всех
		queue_free()
